function C({registerIndicator:x,nulls:d}){x({id:"oa-cv",name:"Conditional Volatility (CV)",category:"Volatility",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:20,min:10,max:500,step:1,tooltip:"Initial period for estimation."},{key:"alpha",type:"number",label:"Alpha",default:.2,min:.01,max:.99,step:.01,tooltip:"Weight on the previous squared return."},{key:"beta",type:"number",label:"Beta",default:.7,min:.01,max:.99,step:.01,tooltip:"Weight on the previous variance. Alpha plus Beta must stay below 1."}],plots:[{key:"cv",type:"line",title:"CV",style:{color:"#ffeb3b",lineWidth:2}}],calc(s,h){const f=s.length,b=Math.min(500,Math.max(10,Math.floor(Number(h.length)||20))),r=Math.min(.99,Math.max(.01,Number(h.alpha)||.2));let m=Math.min(.99,Math.max(.01,Number(h.beta)||.7));r+m>=1&&(m=Math.max(.001,1-r-.001));const v=252,c=1e-10,A=1e-4;let N=0,n=0,o=0;const M=new Array(f).fill(NaN);for(let e=0;e<f;e++){const y=s[e].close,u=e>=1?s[e-1].close:NaN,p=e>=2?s[e-2].close:NaN;let t=Number.isFinite(y)?y:u;Number.isFinite(t)||(t=c),t=Math.max(t,c);let a;Number.isFinite(u)?a=u:Number.isFinite(p)&&p!==0?a=p:a=t,a=Math.max(a,c);let l=0;t>0&&a>0&&(l=Math.log(t/a)),Math.abs(l)>.2&&(l=Math.sign(l)*.2);const g=l*l;e<b?(n=(e*n+g)/(e+1),o=n):e===b&&(N=(1-r-m)*n,o=n);let i=Number.isFinite(o)?o:A;i=N+r*g+m*i,i=Math.max(i,1e-7),o=i,M[e]=Math.sqrt(v*i)*100}return{cv:d(M)}}})}export{C as default};
